mapper.update:
UPDATE t_notification_attempt SET status = #{status}, provider_message_id = COALESCE(#{messageId}, provider_message_id),
    resolution_source = #{source}, update_time = #{now}

    , response_code = #{code}, finished_time = #{now}
    , resolution_code = #{code}

, resolved_time = COALESCE(resolved_time, #{now})
WHERE attempt_id = #{item.attemptId} AND status = #{item.status}

UPDATE t_notification_attempt SET event_outcome = #{outcome}, event_outcome_code = #{code},
    event_outcome_time = #{occurredTime}, update_time = #{now}
WHERE attempt_id = #{item.attemptId} AND event_outcome <=> #{item.eventOutcome}
